// The review's counts, named once for every page (1 Nov 2026, owner: "the screening page has weird counts and very different than
// extraction page"): the rail, Screening, Extraction, Appraisal, the Overview, Reporting and the MCP overview read a count from here, never
// from a reduction of their own (app/test/review-counts-parity.test.mjs). The words (.superpowers/sdd/2026-11-01-chunked-sections/
// counts-inventory.md): a stage's records are decided or to decide (no decision there, or uncertain; awaiting classification is an end);
// at full text the undecided are waiting; included are records, studies the included trials, reports the further reports of a study.
// Each set keeps its ids, so a count opens its set on its page (lib/arrive.mjs). Pure; once per project version.
import { queue, decisionAt, studies as studiesOf, isIncluded, screeningStarted, awaitingClass } from './screen.mjs';
import { reviewStudies, perVersion } from './review-studies.mjs';
import { projectMode } from './workflow.mjs';
import { APPRAISAL_TOOLS, appraisalTool } from '../schema.mjs';

const ids = list => list.map(p => p.id);

const reviewed = (s, p) => Object.values(s.robReview?.records?.[p.id] || {}).some(t => Object.values(t || {}).some(l => ['a', 'b', 'resolved'].some(k => l?.[k] && Object.values(l[k]).some(Boolean))));
/** Whether a study holds a risk-of-bias answer, under its instrument (lib/study-instrument.mjs) or the project's. */
export function appraised(s, p) {
  const rec = s.assessments?.[p.id];
  if (!rec) return reviewed(s, p);
  const own = s.appraisalByStudy?.[p.id];
  if (own && rec[own] && Object.values(rec[own]).some(Boolean)) return true;
  const tool = appraisalTool(s.appraisalTool || 'rob2');
  if (rec[tool.id]) return true;
  if (!own && Object.values(rec).some(v => v && typeof v === 'object' && Object.values(v).some(Boolean))) return true;
  return tool.id === 'rob2' && Object.keys(rec).some(k => !APPRAISAL_TOOLS.some(t => t.id === k));
}

/** One stage: { records, decided, toDecide, include, exclude, uncertain, awaiting, undecided, ids: { records, toDecide, uncertain, undecided } }. */
function stageCounts(s, stage) {
  const { pool, open } = queue(s, stage);
  const t = { include: [], exclude: [], uncertain: [], awaiting: [], undecided: [] };
  for (const p of pool) { const d = decisionAt(s, stage, p.id); (d ? (awaitingClass(d) ? t.awaiting : t[d.decision] || t.undecided) : t.undecided).push(p); }
  return { records: pool.length, decided: pool.length - open.length, toDecide: open.length, include: t.include.length, exclude: t.exclude.length,
    uncertain: t.uncertain.length, awaiting: t.awaiting.length, undecided: t.undecided.length,
    ids: { records: ids(pool), toDecide: ids(open), uncertain: ids(t.uncertain), undecided: ids(t.undecided) } };
}

/** { records, merged, started, ta, ft (with waiting, begun), toDecide, included, studies, reports, provisional, awaiting, extraction, appraisal, ids }. */
export const reviewCounts = perVersion(countsOf);
function countsOf(s) {
  const papers = s.papers || [], workspace = projectMode(s) === 'workspace';
  const r = reviewStudies(s), ta = stageCounts(s, 'ta'), ft = stageCounts(s, 'ft');
  ft.waiting = r.ftStage ? r.waiting.length : ft.undecided; ft.begun = r.ftStage; ft.ids.waiting = r.ftStage ? ids(r.waiting) : ft.ids.undecided;
  const study = studiesOf(s), records = workspace ? papers.filter(p => isIncluded(s, p.id)) : r.records;
  const withValue = new Set();
  for (const k of Object.keys(s.values || {})) { const i = k.indexOf(':'); if (i > 0) withValue.add(k.slice(0, i)); }
  const extracted = study.filter(p => withValue.has(p.id)), rob = study.filter(p => appraised(s, p));
  const started = screeningStarted(s);
  return {
    records: papers.length, merged: (s.merged || []).length, started, ta, ft, toDecide: ta.toDecide + ft.toDecide,
    included: records.length, studies: study.length, reports: workspace ? 0 : r.reports.length, provisional: workspace ? 0 : r.provisional.length,
    awaiting: r.awaiting.length,
    extraction: { studies: study.length, withValues: extracted.length, toExtract: study.length - extracted.length, values: Object.keys(s.values || {}).length,
      proposals: Object.keys(s.proposals || {}).filter(k => k.includes(':')).length },
    appraisal: { studies: study.length, appraised: rob.length, toAppraise: study.length - rob.length },
    ids: { included: ids(records), studies: ids(study), reports: workspace ? [] : ids(r.reports), toExtract: ids(study.filter(p => !withValue.has(p.id))),
      toAppraise: ids(study.filter(p => !appraised(s, p))), awaiting: ids(r.awaiting) },
  };
}
