/** The project a folder holds, joined, for a reader that does not open it (lib/section-files.mjs). */
export const readFolderProject = async (f, opts) => (await sectionFiles.ensure()).readFolderProject(f, opts);
/** The project of uploaded files, its sections joined (lib/folder-import.mjs; lib/section-files.mjs). */
