  const out = {};
  for (const k of Object.keys(head)) if (k in joined) out[k] = joined[k];
  for (const { name } of S.namedSections(head)) {
    if (name === S.ABSTRACTS || name in head) continue;
    if (kept.has(name)) out[name] = reuse[name]; else if (name in joined) out[name] = joined[name];
  }
  for (const k of Object.keys(joined)) if (!(k in out)) out[k] = joined[k];
